const roots:string[]=[];
afterEach(async()=>Promise.all(roots.splice(0).map(x=>rm(x,{recursive:true,force:true}))));
const sample=(file:string):ScoredSample=>({id:'sample-1',ownerId:'user-1',filePath:file,durationMs:6000,capturedAt:1,qualityScore:.9,speechRatio:.8,silenceRatio:.2,rms:.1,peak:.5,clippingRatio:0,snrEstimate:25,reasons:['clean'],isBestSample:false,exceptionalCandidate:false,selectedForRebuild:false,reviewStatus:'pending',active:true,continuity:.8});

describe('production audio and persistence seams',()=>{
  it('creates a standards-compliant PCM WAV',()=>{const pcm=Buffer.alloc(48000*2*2);const wav=wavFromPcm(pcm);expect(wav.subarray(0,4).toString()).toBe('RIFF');expect(wav.subarray(8,12).toString()).toBe('WAVE');expect(wav.readUInt16LE(20)).toBe(1);expect(wav.readUInt32LE(24)).toBe(48000);expect(wav.readUInt32LE(40)).toBe(pcm.length);});
  it('persists review decisions and removes cleared sample files',async()=>{const root=await mkdtemp(path.join(tmpdir(),'voice-bot-'));roots.push(root);const file=path.join(root,'sample.wav');await writeFile(file,wavFromPcm(Buffer.alloc(100)));const db=openDatabase(path.join(root,'bot.db'));const repo=new SampleRepository(db);repo.save('guild-1',sample(file));expect(repo.list('guild-1','user-1')).toHaveLength(1);expect(repo.review('sample-1','user-1','accepted')).toBe(1);expect(repo.get('sample-1')?.selectedForRebuild).toBe(true);expect(repo.history('guild-1','user-1')[0].decision).toBe('accepted');expect(await repo.clear('guild-1','user-1')).toBe(1);await expect(readFile(file)).rejects.toThrow();db.close();});
  it('drains speech in progress before training closes and keeps its WAV',async()=>{const root=await mkdtemp(path.join(tmpdir(),'voice-drain-'));roots.push(root);const scored=sample('');const capture=new VoiceCaptureService(root,{extract:()=>scored} as any,{score:(_f:any,input:any)=>({...scored,...input})} as any);const training=new TrainingSessionManager();training.start('guild-1',['user-1']);const internals=capture as any;internals.activeUsers.set('guild-1',new Set(['user-1']));internals.streams.set('guild-1',new Map());internals.listeners.set('guild-1',()=>{});internals.pending.set('guild-1',new Map([['user-1',new Set()]]));const work=internals.finish('guild-1','user-1',[Buffer.alloc(48_000*2*2*5)],async(s:ScoredSample)=>training.add('guild-1','user-1',s));internals.pending.get('guild-1').get('user-1').add(work);work.finally(()=>internals.pending.get('guild-1')?.get('user-1')?.delete(work));await capture.stopAndDrain('guild-1');const result=await training.stop('guild-1');expect(result[0]?.samples).toHaveLength(1);await expect(access(result[0]!.samples[0]!.filePath!)).resolves.toBeUndefined();});
  it('drains only the removed user while another user remains busy',async()=>{const capture=new VoiceCaptureService();const internals=capture as any;let release!:()=>void;const other=new Promise<void>(resolve=>{release=resolve});internals.activeUsers.set('g',new Set(['a','b']));internals.streams.set('g',new Map());const own=new Set<Promise<void>>();const done=Promise.resolve().finally(()=>own.delete(done));own.add(done);internals.pending.set('g',new Map([['a',own],['b',new Set([other])]]));await expect(capture.removeUserAndDrain('g','a')).resolves.toBeUndefined();expect(internals.pending.get('g').has('b')).toBe(true);release();});
  it('removes both the database row and WAV transactionally',async()=>{const root=await mkdtemp(path.join(tmpdir(),'voice-remove-'));roots.push(root);const file=path.join(root,'sample.wav');await writeFile(file,Buffer.from('wav'));const db=openDatabase(path.join(root,'bot.db'));const repo=new SampleRepository(db);repo.save('guild-1',sample(file));await repo.remove('sample-1');expect(repo.get('sample-1')).toBeUndefined();await expect(access(file)).rejects.toThrow();db.close();});
  it('selects stopped-session samples only from active repository state',async()=>{const training=new TrainingSessionManager();training.start('g',['user-1']);training.add('g','user-1',sample('/gone.wav'));training.add('g','user-1',{...sample('/kept.wav'),id:'kept'});const result=await training.stop('g',undefined,true,new Set(['kept']));expect(result[0]?.samples.map(x=>x.id)).toEqual(['kept']);});
  it('resets a built voice while preserving its profile alias',async()=>{const root=await mkdtemp(path.join(tmpdir(),'voice-reset-'));roots.push(root);const db=openDatabase(path.join(root,'bot.db'));const repo=new VoiceRepository(db);repo.ensureProfile('g','u','Friendly');repo.activate('g','u','provider-secret',0,0);expect(repo.resetVoiceAndQueue('g','u',repo.voiceByOwner('g','u').id)).toBe('provider-secret');expect(repo.voiceByOwner('g','u')).toMatchObject({alias:'Friendly',fish_voice_id:null,model_version:0});db.close();});
  it('rolls back voice reset when durable outbox insertion fails',async()=>{const root=await mkdtemp(path.join(tmpdir(),'voice-rollback-'));roots.push(root);const db=openDatabase(path.join(root,'bot.db'));const repo=new VoiceRepository(db);repo.ensureProfile('g','u','Friendly');repo.activate('g','u','provider-secret',0,0);db.exec("CREATE TRIGGER reject_cleanup BEFORE INSERT ON pending_provider_deletions BEGIN SELECT RAISE(ABORT,'outbox failed'); END");expect(()=>repo.resetVoiceAndQueue('g','u',repo.voiceByOwner('g','u').id)).toThrow('outbox failed');expect(repo.voiceByOwner('g','u').fish_voice_id).toBe('provider-secret');expect(db.prepare('SELECT * FROM pending_provider_deletions').all()).toHaveLength(0);db.close();});
  it('queues the provider model current at the destructive transaction',async()=>{const root=await mkdtemp(path.join(tmpdir(),'voice-race-'));roots.push(root);const db=openDatabase(path.join(root,'bot.db'));const repo=new VoiceRepository(db);repo.ensureProfile('g','u','Friendly');repo.activate('g','u','old',0,0);expect(repo.activate('g','u','replacement',1,1)).toBe(true);expect(repo.deleteOwnerAndQueue('g','u')).toBe('replacement');expect(db.prepare('SELECT remote_id FROM pending_provider_deletions').all()).toEqual([{remote_id:'replacement'}]);expect(repo.voiceByOwner('g','u')).toBeUndefined();db.close();});
  it('persists failed provider deletion and removes it after a later retry',async()=>{const root=await mkdtemp(path.join(tmpdir(),'cleanup-'));roots.push(root);const db=openDatabase(path.join(root,'bot.db'));let fail=true;const provider={deleteVoice:async()=>{if(fail)throw new Error('offline')}} as any;const queue=new ProviderDeletionQueue(db,provider,1000,()=>100);expect(await queue.delete('remote-secret')).toBe('retry_scheduled');expect(db.prepare('SELECT attempts,last_error FROM pending_provider_deletions').get()).toMatchObject({attempts:1,last_error:'offline'});fail=false;expect(await queue.attempt('remote-secret')).toBe('deleted');expect(db.prepare('SELECT * FROM pending_provider_deletions').all()).toHaveLength(0);db.close();});

  it('persists permanent provider failures without scheduling retries',async()=>{const root=await mkdtemp(path.join(tmpdir(),'permanent-'));roots.push(root);const db=openDatabase(path.join(root,'bot.db'));const queue=new ProviderDeletionQueue(db,{deleteVoice:async()=>{throw new FishApiError('unauthorized',401,false)}} as any);expect(await queue.delete('secret')).toBe('permanent_failure');expect(db.prepare('SELECT retryable,last_error FROM pending_provider_deletions WHERE remote_id=?').get('secret')).toMatchObject({retryable:0,last_error:'unauthorized'});db.close();});
  it('persists cleanup requested after deletion shutdown without starting Fish',async()=>{const root=await mkdtemp(path.join(tmpdir(),'stopped-cleanup-'));roots.push(root);const db=openDatabase(path.join(root,'bot.db'));const provider={deleteVoice:vi.fn()};const queue=new ProviderDeletionQueue(db,provider as any);await queue.stopAndDrain();expect(await queue.delete('later')).toBe('retry_scheduled');expect(provider.deleteVoice).not.toHaveBeenCalled();expect(db.prepare('SELECT remote_id FROM pending_provider_deletions').get()).toEqual({remote_id:'later'});db.close();});
  it.each([5000,10000])('does not count a %ims utterance as live backlog',async duration=>{const transcribe={transcribeWav:async()=>({text:'hello'})};const voice={enqueueStream:vi.fn()};const live=new DiscordLiveService(transcribe as any,{} as any,voice as any,3000);const pipeline={active:true,target:()=> 'voice',latency:{record:()=>{}}};const session={pipeline,controller:new AbortController(),groupId:'g'};await (live as any).process('g',session,Buffer.alloc(9600),Date.now()-duration,Date.now(),0);expect(voice.enqueueStream).toHaveBeenCalledOnce();});
  it('drops genuinely stale work before ASR begins',async()=>{let calls=0;const live=new DiscordLiveService({transcribeWav:async()=>{calls++;return {text:'x'}}} as any,{} as any,{} as any,3000);await (live as any).process('g',{pipeline:{active:true},controller:new AbortController()},Buffer.alloc(9600),Date.now()-10_000,Date.now()-3001,0);expect(calls).toBe(0);});
});

import {FishTranscriptionService} from './services/transcription/FishTranscriptionService.js';
import {loadConfig} from './config/env.js';

describe('Fish ASR and deployment configuration',()=>{
  it('uses Fish multipart ASR with the shared Fish key',async()=>{
    const original=globalThis.fetch;let request:RequestInit|undefined;
    globalThis.fetch=async(_url,init)=>{request=init;return new Response(JSON.stringify({text:' hello fish '}),{status:200,headers:{'content-type':'application/json'}});};
    try{await expect(new FishTranscriptionService('fish-key').transcribeWav(new Uint8Array([1,2]))).resolves.toEqual({text:'hello fish'});expect(request?.headers).toEqual({Authorization:'Bearer fish-key'});expect(request?.body).toBeInstanceOf(FormData);expect((request?.body as FormData).get('audio')).toBeInstanceOf(Blob);}finally{globalThis.fetch=original;}
  });
  it('starts from the required production settings',()=>{expect(loadConfig({DISCORD_TOKEN:'d',DISCORD_CLIENT_ID:'c',DISCORD_GUILD_ID:'123456789012345',BOT_COMMAND_CHANNEL_ID:'234567890123456',FISH_API_KEY:'f',DATABASE_URL:'file:/data/bot.db'} as NodeJS.ProcessEnv).DATABASE_URL).toBe('file:/data/bot.db');});
});

import {binaryPlaybackInput,DiscordVoiceRuntime} from './voice/DiscordVoiceRuntime.js';
describe('binary playback input',()=>{
  it('emits binary chunks rather than iterated byte numbers',async()=>{
    const chunks:unknown[]=[];for await(const chunk of binaryPlaybackInput(new Uint8Array([1,2,255])))chunks.push(chunk);
    expect(chunks).toHaveLength(1);expect(Buffer.isBuffer(chunks[0])||chunks[0] instanceof Uint8Array).toBe(true);expect(typeof chunks[0]).not.toBe('number');expect([...chunks[0] as Uint8Array]).toEqual([1,2,255]);
  });
});

describe('runtime regression wiring',()=>{
  it('uses production Fish realtime settings in the live integration script',async()=>{const source=await readFile(new URL('../scripts/liveIntegration.ts',import.meta.url),'utf8');expect(source).toContain("config.FISH_REALTIME_TIMEOUT_MS,config.FISH_TTS_MODEL");});
  it('awaits real shutdown drains without an arbitrary sleep',async()=>{const source=await readFile(new URL('./index.ts',import.meta.url),'utf8');expect(source).toContain('drainInteractions:()=>drainDiscordInteractions(client)');expect(source).toContain('stopProviderCleanup:()=>providerDeletions.stopAndDrain()');expect(source).not.toContain('setTimeout(resolve,250)');});
  it('never interpolates the provider voice id into Discord responses',async()=>{const source=await readFile(new URL('./discord/client.ts',import.meta.url),'utf8');expect(source).not.toContain('using Fish voice ${live.target()}');expect(source).not.toContain('Rebuilt and validated Fish model ${id}');expect(source).toContain('using ${live.displayAlias()}');});
  it('performs atomic local reset and outbox before remote cleanup',async()=>{const source=await readFile(new URL('./discord/client.ts',import.meta.url),'utf8');const command=source.slice(source.indexOf("i.commandName==='deletevoice'"),source.indexOf("i.commandName==='train'"));expect(command).toContain('repo.resetVoiceAndQueue');expect(command.indexOf('repo.resetVoiceAndQueue')).toBeLessThan(command.indexOf('s.providerDeletions.attempt'));expect(command).not.toContain('providerDeletions.enqueue');});
  it('refuses leave during training and otherwise stops live before leaving',async()=>{const source=await readFile(new URL('./discord/client.ts',import.meta.url),'utf8');const command=source.slice(source.indexOf("i.commandName==='leave'"),source.indexOf("i.commandName==='stop'"));expect(command).toContain('Training is active; run /train stop before /leave.');expect(command.indexOf('s.live.stop')).toBeLessThan(command.indexOf('s.voice.leave'));expect(command).not.toContain('s.training.stop');});
  it('uses one idempotent decoder completion path with error discard semantics',async()=>{const source=await readFile(new URL('./voice/VoiceCaptureService.ts',import.meta.url),'utf8');expect(source).toContain("decoder.once('error',error=>complete(false,error))");expect(source).toContain("decoder.once('end',()=>complete(cleanEnding))");expect(source).toContain('if(completed)return');});
});

describe('final hardening regressions',()=>{
  it('drops an utterance made stale by ASR and one made stale in the playback queue',async()=>{
    let now=1_000;const clock=vi.spyOn(Date,'now').mockImplementation(()=>now);try{
      const voice={enqueueStream:vi.fn()};const transcribe={transcribeWav:async()=>{now=4_001;return {text:'late'}}};const live=new DiscordLiveService(transcribe as any,{} as any,voice as any,3000);const session={pipeline:{active:true,target:()=> 'v',latency:{record:vi.fn()}},controller:new AbortController(),groupId:'g'};
      await (live as any).process('g',session,Buffer.alloc(9600),-9_000,1_000,0);expect(voice.enqueueStream).not.toHaveBeenCalled();
      now=2_000;transcribe.transcribeWav=async()=>({text:'queued'});await (live as any).process('g',session,Buffer.alloc(9600),-8_000,2_000,1);expect(voice.enqueueStream).toHaveBeenCalledOnce();now=5_001;const play=voice.enqueueStream.mock.calls[0]![2];await expect(play({write:()=>true},new AbortController().signal)).rejects.toThrow('stale');
    }finally{clock.mockRestore();}
  });
  it('uses capture minimum independently from best-sample duration',async()=>{const root=await mkdtemp(path.join(tmpdir(),'capture-min-'));roots.push(root);const captured:ScoredSample[]=[];const base=sample('');const capture=new VoiceCaptureService(root,{extract:()=>base} as any,{score:(f:any,input:any)=>({...base,...input,durationMs:f.durationMs??3000})} as any,30_000,undefined,2_000);const x=capture as any;x.activeUsers.set('g',new Set(['u']));await x.finish('g','u',[Buffer.alloc(48_000*2*2)],async(s:ScoredSample)=>captured.push(s));await x.finish('g','u',[Buffer.alloc(48_000*2*2*3)],async(s:ScoredSample)=>captured.push(s));expect(captured).toHaveLength(1);
  });
  it('advances pending review candidates and records each decision once',async()=>{const root=await mkdtemp(path.join(tmpdir(),'review-'));roots.push(root);const db=openDatabase(path.join(root,'bot.db'));const repo=new SampleRepository(db);repo.save('g',{...sample('/a'),id:'a',qualityScore:.95});repo.save('g',{...sample('/b'),id:'b',qualityScore:.9});expect(repo.pendingReviewCandidates('g','user-1')[0]?.id).toBe('a');expect(repo.review('a','user-1','accepted')).toBe(1);expect(repo.review('a','user-1','rejected')).toBe(0);expect(repo.pendingReviewCandidates('g','user-1')[0]?.id).toBe('b');expect(repo.history('g','user-1')).toHaveLength(1);db.close();});
  it('single-flights concurrent deletes and drains command-triggered work',async()=>{const root=await mkdtemp(path.join(tmpdir(),'single-flight-'));roots.push(root);const db=openDatabase(path.join(root,'bot.db'));let release!:()=>void;const gate=new Promise<void>(r=>release=r);const provider={deleteVoice:vi.fn(async()=>gate)} as any;const queue=new ProviderDeletionQueue(db,provider);const a=queue.delete('same');const b=queue.attempt('same');const stopped=queue.stopAndDrain();await Promise.resolve();expect(provider.deleteVoice).toHaveBeenCalledOnce();let drained=false;void stopped.then(()=>drained=true);await Promise.resolve();expect(drained).toBe(false);release();expect(await Promise.all([a,b])).toEqual(['deleted','deleted']);await stopped;db.close();});
});

describe('review follow-up hardening',()=>{
  it('allows only one competing review decision and scopes history to the guild',async()=>{const root=await mkdtemp(path.join(tmpdir(),'review-race-'));roots.push(root);const db=openDatabase(path.join(root,'bot.db'));const repo=new SampleRepository(db);repo.save('guild-a',{...sample('/a'),id:'race'});repo.save('guild-b',{...sample('/b'),id:'other'});repo.review('other','user-1','accepted');const decisions=await Promise.all([Promise.resolve().then(()=>repo.review('race','user-1','accepted')),Promise.resolve().then(()=>repo.review('race','user-1','rejected'))]);expect(decisions.sort()).toEqual([0,1]);expect(repo.history('guild-a','user-1').map(x=>x.sample_id)).toEqual(['race']);expect(repo.history('guild-b','user-1').map(x=>x.sample_id)).toEqual(['other']);db.close();});
  it('releases failed or abandoned reservation capacity',async()=>{const root=await mkdtemp(path.join(tmpdir(),'reservation-release-'));roots.push(root);const data=path.join(root,'training');await import('node:fs/promises').then(fs=>fs.mkdir(data));const db=openDatabase(path.join(root,'bot.db'));const repo=new SampleRepository(db);const abandoned=await repo.reserveStorage(100,100,data);abandoned.release();const replacement=await repo.reserveStorage(100,100,data);replacement.release();db.close();});
  it('does not double-count committed storage reservations',async()=>{const root=await mkdtemp(path.join(tmpdir(),'reserve-'));roots.push(root);const data=path.join(root,'training');await import('node:fs/promises').then(fs=>fs.mkdir(data));const db=openDatabase(path.join(root,'bot.db'));const repo=new SampleRepository(db);const first=await repo.reserveStorage(60,100,data);const firstFile=path.join(data,'first.wav');first.bind(firstFile);await writeFile(firstFile,Buffer.alloc(60));const secondPromise=repo.reserveStorage(40,100,data);let admitted=false;void secondPromise.then(()=>admitted=true);await Promise.resolve();expect(admitted).toBe(false);first.commit();const second=await secondPromise;second.release();await expect(repo.reserveStorage(41,100,data)).rejects.toThrow('storage limit');db.close();});
  it('uses a documented realtime default and rejects HTTP-only realtime models',()=>{const base={DISCORD_TOKEN:'d',DISCORD_CLIENT_ID:'c',DISCORD_GUILD_ID:'123456789012345',BOT_COMMAND_CHANNEL_ID:'234567890123456',FISH_API_KEY:'f',DATABASE_URL:'file:/x'};expect(loadConfig(base as NodeJS.ProcessEnv).FISH_REALTIME_MODEL).toBe('s2-pro');expect(()=>loadConfig({...base,FISH_REALTIME_MODEL:'s2.1-pro'} as NodeJS.ProcessEnv)).toThrow();});
});


describe('live receive stream lifecycle',()=>{
  const harness=(maxUtteranceMs=120000)=>{const speaking=new EventEmitter();const sources:PassThrough[]=[];const decoders:PassThrough[]=[];const decoder=vi.spyOn(prism.opus,'Decoder').mockImplementation((()=>{const stream=new PassThrough();decoders.push(stream);return stream;}) as any);const connection={receiver:{speaking,subscribe:()=>{const stream=new PassThrough();sources.push(stream);return stream;}}};const transcription={transcribeWav:vi.fn(async()=>({text:''}))};const live=new DiscordLiveService(transcription as any,{} as any,{cancelGroup:vi.fn()} as any,3000,maxUtteranceMs);live.start('g',connection as any,'u','voice');speaking.emit('start','u');return {live,sources,decoders,transcription,decoder};};
  it('idempotently handles decoder errors without leaking or transcribing',async()=>{const h=harness();h.decoders[0]!.emit('error',new Error('decode'));await h.live.stop('g');expect(h.transcription.transcribeWav).not.toHaveBeenCalled();h.decoder.mockRestore();});
  it.each(['error','close'] as const)('idempotently handles source %s',async event=>{const h=harness();if(event==='error')h.sources[0]!.emit(event,new Error('source'));else h.sources[0]!.emit(event);await h.live.stop('g');expect(h.transcription.transcribeWav).not.toHaveBeenCalled();h.decoder.mockRestore();});
  it('terminates at max duration and stop drains an active stream',async()=>{const h=harness(5);h.decoders[0]!.write(Buffer.alloc(9600));await new Promise(resolve=>setTimeout(resolve,10));await expect(h.live.stop('g')).resolves.toBe(true);expect((h.live as any).sessions.size).toBe(0);h.decoder.mockRestore();});
  it('stop safely destroys an active receive stream',async()=>{const h=harness();await expect(h.live.stop('g')).resolves.toBe(true);expect(h.sources[0]!.destroyed).toBe(true);expect(h.decoders[0]!.destroyed).toBe(true);h.decoder.mockRestore();});
});

import {shutdownRuntime} from './shutdown.js';
import {createDiscordClient,drainDiscordInteractions,validateTrainingTargets} from './discord/client.js';

describe('storage reconciliation and shutdown',()=>{
  it('reconciles only managed generated WAV files and recovers capacity',async()=>{const root=await mkdtemp(path.join(tmpdir(),'reconcile-'));roots.push(root);const managed=path.join(root,'training'),guild='123456789012345',owner='234567890123456',dir=path.join(managed,guild,owner);await import('node:fs/promises').then(fs=>fs.mkdir(dir,{recursive:true}));const orphan=path.join(dir,'11111111-1111-4111-8111-111111111111.wav'),kept=path.join(dir,'22222222-2222-4222-8222-222222222222.wav'),missing=path.join(dir,'33333333-3333-4333-8333-333333333333.wav'),outside=path.join(root,'outside.wav');await Promise.all([writeFile(orphan,Buffer.alloc(40)),writeFile(kept,Buffer.alloc(60)),writeFile(outside,Buffer.alloc(5))]);const db=openDatabase(path.join(root,'bot.db'));const repo=new SampleRepository(db);repo.save(guild,{...sample(kept),id:'kept'});repo.save(guild,{...sample(missing),id:'missing'});expect(await repo.reconcileManagedStorage(managed)).toEqual({removedOrphans:1,deactivatedMissing:1});await expect(access(orphan)).rejects.toThrow();await expect(access(kept)).resolves.toBeUndefined();await expect(access(outside)).resolves.toBeUndefined();expect(repo.get('missing')?.active).toBe(false);const capacity=await repo.reserveStorage(40,100,managed);capacity.release();db.close();});
  it('retains failed cleanup tombstones and removes metadata after the managed file is gone',async()=>{const root=await mkdtemp(path.join(tmpdir(),'tombstone-'));roots.push(root);const managed=path.join(root,'training'),file=path.join(managed,'123456789012345','234567890123456','44444444-4444-4444-8444-444444444444.wav');await import('node:fs/promises').then(fs=>fs.mkdir(file,{recursive:true}));const db=openDatabase(path.join(root,'bot.db')),repo=new SampleRepository(db);repo.save('123456789012345',{...sample(file),id:'tomb'});repo.review('tomb','234567890123456','rejected');db.prepare('UPDATE samples SET active=0 WHERE id=?').run('tomb');await repo.reconcileManagedStorage(managed);expect(repo.get('tomb')).toBeDefined();await rm(file,{recursive:true});await repo.reconcileManagedStorage(managed);expect(repo.get('tomb')).toBeUndefined();expect(db.prepare('SELECT * FROM sample_reviews WHERE sample_id=?').all('tomb')).toHaveLength(0);db.close();});
  it('waits for a blocked interaction before cleanup and closes DB last despite failures',async()=>{let release!:()=>void;const gate=new Promise<void>(r=>release=r);const order:string[]=[];const run=shutdownRuntime({drainInteractions:async()=>{order.push('drain-start');await gate;order.push('drain-end')},stopCapture:async()=>{order.push('capture');throw new Error('capture')},stopLive:async()=>{order.push('live')},stopVoice:async()=>{order.push('voice')},stopProviderCleanup:async()=>{order.push('provider')},client:{destroy:()=>order.push('client')},db:{close:()=>order.push('db')}} as any);await Promise.resolve();expect(order).toEqual(['drain-start']);release();await run;expect(order.indexOf('drain-end')).toBeLessThan(order.indexOf('capture'));expect(order.at(-1)).toBe('db');});
});

