describe('clean decoder flushing',()=>{it('includes PCM emitted only from decoder flush before persisting',async()=>{const {Transform}=await import('node:stream');const final=Buffer.alloc(48_000*2*2,7),decoderMock=vi.spyOn(prism.opus,'Decoder').mockImplementation((()=>new Transform({transform(chunk,_encoding,callback){callback(null,chunk)},flush(callback){this.push(final);callback()}})) as any);const root=await mkdtemp(path.join(tmpdir(),'flush-'));roots.push(root);const speaking=new EventEmitter(),source=new PassThrough();let extracted=0;const base=sample(''),capture=new VoiceCaptureService(root,{extract:(pcm:Int16Array)=>{extracted=pcm.length;return base}} as any,{score:(_f:any,input:any)=>({...base,...input})} as any,30_000,undefined,1);capture.start('g',{receiver:{speaking,subscribe:()=>source}} as any,['u'],()=>true);speaking.emit('start','u');source.write(Buffer.alloc(48_000*2*2));source.end();for(let n=0;n<100&&extracted===0;n++)await new Promise(r=>setTimeout(r,2));expect(extracted).toBe((48_000*2*2+final.length)/2);await capture.stopAndDrain('g');decoderMock.mockRestore()})});

