describe('live model consistency',()=>{const config=loadConfig({DISCORD_TOKEN:'d',DISCORD_CLIENT_ID:'c',DISCORD_GUILD_ID:'123456789012345',BOT_COMMAND_CHANNEL_ID:'234567890123456',FISH_API_KEY:'f',DATABASE_URL:'file:/x'} as NodeJS.ProcessEnv);const rebuild=async(target:string)=>{const order:string[]=[],repo={voice:vi.fn(()=>({id:1,alias:'Voice',owner_id:'owner',fish_voice_id:'old',model_version:1,state_revision:1})),activate:vi.fn(()=>{order.push('activate');return true}),voiceByOwner:vi.fn(()=>({alias:'Voice'}))} as any;const live={status:vi.fn(()=>({target:()=>target})),switchVoice:vi.fn(()=>{order.push('switch');return true}),stop:vi.fn()};const deletions={delete:vi.fn(async()=>{order.push('delete');return 'deleted'})};const services={builder:{build:vi.fn(async()=>({id:'new'}))},samples:{list:vi.fn(()=>[sample('/x')]),eligible:vi.fn(()=>[sample('/x')])},fish:{synthesize:vi.fn(async()=>new Uint8Array([1]))},live,providerDeletions:deletions,training:{status:vi.fn()},capture:{},voice:{}} as any;const client=createDiscordClient(config,repo,services),interaction={isButton:()=>false,isChatInputCommand:()=>true,isCommand:()=>true,isRepliable:()=>true,commandName:'train',guildId:config.DISCORD_GUILD_ID,channelId:config.BOT_COMMAND_CHANNEL_ID,user:{id:'owner'},guild:{},options:{getSubcommand:()=> 'rebuild',getString:()=> 'Voice'},deferReply:vi.fn(async()=>{}),editReply:vi.fn(async()=>{})};client.emit('interactionCreate',interaction as any);await drainDiscordInteractions(client);return {order,live,deletions}};it('switches OLD to NEW before durable OLD deletion',async()=>{const x=await rebuild('old');expect(x.order).toEqual(['activate','switch','delete']);expect(x.live.switchVoice).toHaveBeenCalledWith(config.DISCORD_GUILD_ID,'new','Voice')});it('does not switch an unrelated live target',async()=>{const x=await rebuild('other');expect(x.order).toEqual(['activate','delete']);expect(x.live.switchVoice).not.toHaveBeenCalled()});it('rechecks the exact destructive transaction model before provider deletion',async()=>{const events:string[]=[],status=vi.fn().mockReturnValueOnce({sourceUserId:'other',target:()=> 'other'}).mockReturnValue({sourceUserId:'other',target:()=> 'new'}),live={status,stop:vi.fn(async()=>{events.push('stop')})},repo={voiceByOwner:vi.fn(()=>({fish_voice_id:'old'})),deleteOwnerAndQueue:vi.fn(()=> 'new')} as any,services={capture:{removeUserAndDrain:vi.fn()},training:{cancelUser:vi.fn()},samples:{purge:vi.fn()},live,providerDeletions:{attempt:vi.fn(async()=>{events.push('delete');return 'deleted'})},voice:{},fish:{},builder:{}} as any;const client=createDiscordClient(config,repo,services),i={isButton:()=>false,isChatInputCommand:()=>true,isCommand:()=>true,isRepliable:()=>true,commandName:'deletedata',guildId:config.DISCORD_GUILD_ID,channelId:config.BOT_COMMAND_CHANNEL_ID,user:{id:'owner'},guild:{},reply:vi.fn(async()=>{})};client.emit('interactionCreate',i as any);await drainDiscordInteractions(client);expect(events).toEqual(['stop','delete'])});it('looks up the live model only after awaited join completes',async()=>{let release!:()=>void,current='old';const gate=new Promise<void>(r=>release=r),repo={voice:vi.fn(()=>({fish_voice_id:current,alias:'Voice'}))} as any,live={start:vi.fn(),status:vi.fn(),stop:vi.fn()},services={training:{status:vi.fn()},voice:{join:vi.fn(async()=>gate)},live,fish:{},samples:{},capture:{},builder:{},providerDeletions:{}} as any;const client=createDiscordClient(config,repo,services),i={isButton:()=>false,isChatInputCommand:()=>true,isCommand:()=>true,isRepliable:()=>true,commandName:'live',guildId:config.DISCORD_GUILD_ID,channelId:config.BOT_COMMAND_CHANNEL_ID,user:{id:'owner'},guild:{voiceAdapterCreator:{}},member:{voice:{channel:{id:'voice'}}},options:{getSubcommand:()=> 'start',getString:()=> 'Voice'},reply:vi.fn(async()=>{})};client.emit('interactionCreate',i as any);await Promise.resolve();expect(repo.voice).not.toHaveBeenCalled();current='new';release();await drainDiscordInteractions(client);expect(live.start).toHaveBeenCalledWith(config.DISCORD_GUILD_ID,undefined,'owner','new','Voice')})});

describe('live decoder flushing',()=>{it('transcribes PCM emitted during a clean decoder flush',async()=>{const {Transform}=await import('node:stream'),final=Buffer.alloc(9600,9);const decoderMock=vi.spyOn(prism.opus,'Decoder').mockImplementation((()=>new Transform({transform(chunk,_encoding,callback){callback(null,chunk)},flush(callback){this.push(final);callback()}})) as any),speaking=new EventEmitter(),source=new PassThrough();let wavLength=0;const transcription={transcribeWav:vi.fn(async(wav:Uint8Array)=>{wavLength=wav.length;return {text:''}})},live=new DiscordLiveService(transcription as any,{} as any,{cancelGroup:vi.fn()} as any,3000);live.start('g',{receiver:{speaking,subscribe:()=>source}} as any,'u','voice');speaking.emit('start','u');source.write(Buffer.alloc(9600));source.end();for(let n=0;n<100&&!wavLength;n++)await new Promise(r=>setTimeout(r,2));expect(wavLength).toBe(44+9600+final.length);await live.stop('g');decoderMock.mockRestore()})});

